(() => {
  'use strict';

  const root = document.getElementById('a-side-root');
  if (!root) return;

  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));
  const sections = ['concept', 'service', 'works', 'about', 'contact']
    .map(id => document.getElementById(id))
    .filter(Boolean);

  root.classList.add('tatsu-accent-v4');

  /* Copy the actual Pixel B generated by the B-side. No redraw or substitute. */
  const bPixel = document.getElementById('pixelGrid');
  const topBButton = root.querySelector('.side-choice > button');
  const oldTopBSvg = topBButton?.querySelector('svg');
  if (bPixel && topBButton && oldTopBSvg) {
    const topPixel = bPixel.cloneNode(true);
    topPixel.id = 'topPixelGrid';
    topPixel.classList.add('side-b-pixel-grid');
    topPixel.setAttribute('aria-hidden', 'true');
    Array.from(topPixel.children).forEach((pixel, index) => {
      pixel.style.setProperty('--pixel-index', String(index));
      pixel.style.setProperty('--pixel-x', `${((index % 8) - 3.5) * 18}px`);
      pixel.style.setProperty('--pixel-y', `${((Math.floor(index / 8) % 4) - 1.5) * 15}px`);
    });
    oldTopBSvg.replaceWith(topPixel);
  }

  /* Add the third Works door specified in the PPT and keep existing datasets. */
  const works = document.getElementById('works');
  const collectionTabs = works?.querySelector('.home-collection-tabs');
  const studioButton = collectionTabs?.querySelector('[data-home-collection="studio"]');
  let otherButton = collectionTabs?.querySelector('[data-home-collection="other"]');
  if (studioButton) studioButton.textContent = 'Tatsumaki Works';
  if (collectionTabs && !otherButton) {
    otherButton = document.createElement('button');
    otherButton.type = 'button';
    otherButton.dataset.homeCollection = 'other';
    otherButton.setAttribute('aria-selected', 'false');
    otherButton.textContent = 'Other Works';
    collectionTabs.appendChild(otherButton);
  }

  function activateWorksDoor(mode) {
    if (!works) return;
    const selectedPanel = document.getElementById('home-selected-panel');
    const studioPanel = document.getElementById('home-studio-panel');
    works.dataset.workMode = mode;
    collectionTabs?.querySelectorAll('[data-home-collection]').forEach(button => {
      button.setAttribute('aria-selected', String(button.dataset.homeCollection === mode));
    });
    selectedPanel?.classList.toggle('is-active', mode === 'selected');
    studioPanel?.classList.toggle('is-active', mode !== 'selected');
    if (mode === 'studio') studioPanel?.querySelector('[data-home-studio="Branding"]')?.click();
    if (mode === 'other') studioPanel?.querySelector('[data-home-studio="Other"]')?.click();
    const activePanel = mode === 'selected' ? selectedPanel : studioPanel;
    activePanel?.querySelectorAll('[data-tatsu-reveal]').forEach(element => element.classList.add('is-tatsu-visible'));
  }

  collectionTabs?.querySelectorAll('[data-home-collection]').forEach(button => {
    button.onclick = () => activateWorksDoor(button.dataset.homeCollection);
  });
  activateWorksDoor('selected');

  /* Reflow the existing About content into the PPT's portrait-left / copy-right layout. */
  const about = document.getElementById('about');
  const aboutLayout = about?.querySelector(':scope > div:last-child > div');
  const aboutProfile = aboutLayout?.firstElementChild;
  const aboutPhoto = aboutProfile?.firstElementChild;
  if (aboutLayout && aboutProfile && aboutPhoto) {
    aboutPhoto.remove();
    aboutPhoto.classList.add('about-photo-v4');
    aboutProfile.classList.add('about-copy-v4');
    aboutLayout.prepend(aboutPhoto);
  }

  /* Full-width chromatic masses and a smaller parallax field for every section. */
  sections.forEach(section => {
    if (!section.querySelector(':scope > .accent-sweep')) {
      const sweep = document.createElement('i');
      sweep.className = 'accent-sweep';
      sweep.setAttribute('aria-hidden', 'true');
      section.prepend(sweep);
    }
    if (!section.querySelector(':scope > .accent-decor')) {
      const decor = document.createElement('i');
      decor.className = 'accent-decor';
      decor.setAttribute('aria-hidden', 'true');
      section.appendChild(decor);
    }
  });

  /* Service words become independent kinetic typography. */
  const service = document.getElementById('service');
  const serviceWords = Array.from(service?.querySelectorAll('.service-en') || []);
  serviceWords.forEach(word => {
    const text = word.textContent || '';
    word.setAttribute('aria-label', text);
    word.textContent = '';
    Array.from(text).forEach((character, index) => {
      const span = document.createElement('span');
      span.className = 'service-en-char';
      span.setAttribute('aria-hidden', 'true');
      span.style.setProperty('--char-index', String(index));
      span.textContent = character === ' ' ? '\u00a0' : character;
      word.appendChild(span);
    });
  });

  const serviceStages = service ? [
    { element: service.querySelector('.service-heading'), at: .035 },
    { element: service.querySelector('.flow-left'), at: .14 },
    { element: service.querySelector('.flow-right'), at: .28 },
    { element: service.querySelector('.service-bridge'), at: .53 },
    { element: service.querySelector('.service-card:nth-child(1)'), at: .65 },
    { element: service.querySelector('.service-card:nth-child(2)'), at: .76 },
    { element: service.querySelector('.service-card:nth-child(3)'), at: .87 }
  ].filter(stage => stage.element) : [];

  if (service && !reduced) service.classList.add('accent-sequence-ready');
  if (reduced) serviceStages.forEach(stage => stage.element.classList.add('is-accent-live'));

  let ticking = false;

  function renderAccentMotion() {
    ticking = false;
    if (root.style.display === 'none') return;
    const viewport = window.innerHeight || 1;

    sections.forEach((section, index) => {
      const rect = section.getBoundingClientRect();
      const sectionProgress = clamp((viewport - rect.top) / (viewport + rect.height));
      const entryProgress = clamp((viewport - rect.top) / (viewport * .92));
      const sweepX = -118 + entryProgress * 244;
      section.style.setProperty('--sweep-x', `${sweepX.toFixed(2)}vw`);
      section.style.setProperty('--accent-turn', `${(sectionProgress * 560 + index * 22).toFixed(2)}deg`);
      section.style.setProperty('--decor-y', `${((.5 - sectionProgress) * 120).toFixed(2)}px`);
      section.style.setProperty('--decor-turn', `${(sectionProgress * -80).toFixed(2)}deg`);
      section.style.setProperty('--decor-scale', (0.82 + sectionProgress * 0.42).toFixed(3));
    });

    if (service) {
      const rect = service.getBoundingClientRect();
      const serviceProgress = clamp((viewport * .82 - rect.top) / (rect.height * .82 + viewport * .4));
      serviceStages.forEach(stage => {
        stage.element.classList.toggle('is-accent-live', reduced || serviceProgress >= stage.at);
      });
      service.style.setProperty('--diagram-scale', (0.84 + serviceProgress * .16).toFixed(4));
    }

    if (about) {
      const rect = about.getBoundingClientRect();
      const progress = clamp((viewport - rect.top) / (viewport + rect.height));
      about.style.setProperty('--about-band-x', `${(18 - progress * 24).toFixed(2)}%`);
    }

    const contact = document.getElementById('contact');
    if (contact) {
      const rect = contact.getBoundingClientRect();
      const progress = clamp((viewport - rect.top) / (viewport + rect.height));
      contact.style.setProperty('--contact-dot-scale', (0.82 + progress * .54).toFixed(3));
      contact.style.setProperty('--contact-dot-turn', `${(-18 + progress * 48).toFixed(2)}deg`);
    }
  }

  function requestRender() {
    if (ticking) return;
    ticking = true;
    window.requestAnimationFrame(renderAccentMotion);
  }

  window.addEventListener('scroll', requestRender, { passive: true });
  window.addEventListener('resize', requestRender, { passive: true });
  requestRender();
})();
